(() => {
'use strict';
const $=id=>document.getElementById(id),v=id=>$(id)?.value||'',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uniq=a=>[...new Set(a)],join=a=>a?.length?a.join(', '):'—';
const CSS='*{box-sizing:border-box}body{margin:0;color:#142d42;background:#e9eff4;font:12px Arial,sans-serif}.tools{padding:12px;display:flex;gap:10px;justify-content:center}button{padding:8px 14px;border:1px solid #aac2d3;border-radius:7px;background:white;color:#143951;cursor:pointer}.sheet{width:190mm;height:277mm;margin:12px auto;padding:6mm;background:white;overflow:hidden}.content{transform-origin:top left}h1{font-size:20px;color:#165e79;margin:0 0 7px}h2{font-size:13px;padding:5px;background:#edf4f8;color:#164d65;margin:8px 0 4px}p{margin:4px 0;line-height:1.35;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #bccbd5;padding:4px;vertical-align:top;overflow-wrap:anywhere}th{background:#e7f1f6;text-align:left}.verdict{border-left:4px solid #348865;padding:6px;background:#edf7f0}.notes{white-space:pre-wrap}.muted{color:#496376}@page{size:A4 portrait;margin:10mm}@media print{body{background:white}.tools{display:none}.sheet{margin:0;padding:6mm;width:190mm;height:277mm;break-after:avoid}}';
function build(model,options={}) {
 if(!model?.ready)throw Error('Calculate the chart before preparing the query sheet.');
 const method=options.method==='sixfold'?'sixfold':'fourfold',event=(options.catalogue==='handbook'?KPHandbook:KPPrediction).getCatalogue().events.find(e=>String(e.id)===String(options.eventId));
 if(!event)throw Error('Select a query from the event catalogue.');
 const cusp=Number(options.cusp||event.mainHouses?.[0]||1),analysis=KPEventPromise.analyze(model,{cusp,method,event,layers:['CSL','STL','SBL']}),verdict=KPEventOutcome.assess(analysis);
 if(!analysis.ready)throw Error(analysis.reason);
 const fields=method==='sixfold'?['A','B','C','D','E','F']:['A','B','C','D'];
 const supporting=uniq(event.supportingGroups.flat()),cusps=uniq([cusp,...supporting]);
 const levels=cusps.map(id=>({id,...Object.fromEntries(fields.map(f=>[f,[...(model[method].houses.find(h=>h.id===id)?.[f]||[])]]))}));
 const total=uniq(levels.flatMap(r=>fields.flatMap(f=>r[f]))),moon=model.planets.find(p=>p.id==='Mo'),saturn=model.planets.find(p=>p.id==='Sa'),asc=model.houses.find(h=>h.id===1);
 const connected=(p,id)=>p&&(p.stl===id||p.sl===id||p.conj?.includes(id)||p.aspd?.includes(id)||p.aspg?.planets?.includes(id));
 const links=[];if(connected(moon,'Sa'))links.push('Moon → Saturn');if(connected(saturn,'Mo'))links.push('Saturn → Moon');
 const date=options.date||v('dob'),day=['Su','Mo','Ma','Me','Ju','Ve','Sa'][new Date(date+'T12:00:00Z').getUTCDay()];
 const rp=[{label:'Day',sgl:day,stl:'—',sl:'—'},{label:'Ascendant',sgl:asc.sgl,stl:asc.stl,sl:asc.sl},{label:'Moon',sgl:moon.sgl,stl:moon.stl,sl:moon.sl}];
 const ruling=uniq(rp.flatMap(r=>[r.sgl,r.stl,r.sl]).filter(id=>id&&id!=='—')),common=total.filter(id=>ruling.includes(id));
 let periods=[],periodReason='';try{periods=(options.periods||KPDashaFal.current(model,new Date()).periods).map(p=>({...p,star:model.planets.find(x=>x.id===p.id)?.stl,sub:model.planets.find(x=>x.id===p.id)?.sl}));}catch(e){periodReason=e.message;}
 const periodChecks=periods.map(p=>{const row=model[method].planets.find(r=>r.id===p.id),houses=uniq(fields.flatMap(f=>row?.[f]||[])),proofs=analysis.rule.groups.map(required=>({required,matched:required.filter(h=>houses.includes(h)),missing:required.filter(h=>!houses.includes(h))})),best=[...proofs].sort((a,b)=>a.missing.length-b.missing.length)[0],verdict=KPEventOutcome.assess({...analysis,layers:[],houses,proofs,best});return {...p,houses,verdict};});
 return {ready:true,periodChecks,periodMode:options.periodMode||'current',eventId:event.id,query:event.event.en||event.event.mr,method,fields,cusp,supporting,analysis,verdict,levels,total,rp,ruling,common,filterRP:ruling.length>(method==='sixfold'?6:4),punarphoo:links.length>0,punarphooProof:links.join('; ')||'No Moon–Saturn lord, conjunction or aspect connection in the chart model.',periods,periodReason,date,time:v('birthTime'),place:v('birthPlace'),horaryNumber:v('horary-number'),chartKind:v('chart-kind'),question:options.question||'',opinion:options.opinion||''};
}
function data(){return build(currentKPModel,{eventId:v('hq-event'),catalogue:$('hq-event')?.dataset.catalogue,cusp:$('hq-event')?.dataset.catalogue==='handbook'?Number(v('ep-cusp')):undefined,method:v('hq-method'),question:v('hq-question'),opinion:v('hq-opinion'),periods:window.KPHoraryDBA?.periods(),periodMode:window.KPHoraryDBA?.mode()});}
function snapshot(d=data()) {
 const rows=(a,cols)=>a.map(r=>'<tr>'+cols.map(k=>'<td>'+esc(Array.isArray(r[k])?join(r[k]):r[k]??'—')+'</td>').join('')+'</tr>').join('');
 const title=d.verdict.qualified?'House criteria matched · additional rule review required':d.verdict.promised?'Event is promised by the selected house criteria':'Event is not promised by the selected house criteria';
 return '<div class="content"><h1>KP MASTER · Horary Query Results</h1><p><strong>'+esc(d.method==='sixfold'?'Six-fold A–F':'Four-fold A–D')+' · '+esc(d.query)+'</strong></p><p>Question: '+esc(d.question||d.query)+'</p><p>'+esc(d.chartKind==='horary'?'Horary no. '+d.horaryNumber:'Natal chart reference')+' · '+esc(d.date+' '+d.time+' · '+d.place)+'</p><h2>Script · Cuspal lord chain</h2><p>Main cusp: '+d.cusp+' · Supporting cusps: '+esc(join(d.supporting))+'</p><table><thead><tr><th>Lord chain</th><th>Planet</th><th>Signifying houses</th></tr></thead><tbody>'+rows(d.analysis.layers.filter(r=>['CSL','STL','SBL'].includes(r.role)),['label','id','houses'])+'</tbody></table><p>Combined significators: '+esc(join(d.analysis.houses))+' · Required alternatives: '+esc(d.analysis.rule.groups.map(join).join(' OR '))+'</p><div class="verdict"><strong>'+esc(title)+'</strong><p>'+esc(d.verdict.reason)+'</p>'+(d.verdict.qualified?'<p>'+esc(d.analysis.rule.remarks||join(d.analysis.rule.issues))+'</p>':'')+'</div><h2>Ruling planets · selected chart moment</h2><table><thead><tr><th>Point</th><th>Sign / Day lord</th><th>Star lord</th><th>Sub lord</th></tr></thead><tbody>'+rows(d.rp,['label','sgl','stl','sl'])+'</tbody></table><p>RP: '+esc(join(d.ruling))+' · Common significators / RP'+(d.filterRP?' (source threshold exceeded)':'')+': '+esc(join(d.common))+'</p><p>Punarphoo connection: <strong>'+(d.punarphoo?'YES · delay indication':'NO')+'</strong> · '+esc(d.punarphooProof)+'</p><h2>'+esc(d.method==='sixfold'?'Six-fold':'Four-fold')+' cusp significators</h2><table><thead><tr><th>Cusp</th>'+d.fields.map(f=>'<th>'+f+'</th>').join('')+'</tr></thead><tbody>'+rows(d.levels,['id',...d.fields])+'</tbody></table><p>Total significators: '+esc(join(d.total))+'</p><p class="muted">'+esc(d.method==='sixfold'?'A Sub of occupant · B Star of occupant · C Occupant · D Sub of owner · E Star of owner · F Owner':'A Star of occupant · B Occupant · C Star of owner · D Owner')+'</p><h2>Joint period · '+esc(d.periodMode==='selected'?'Selected DBA':'Current DBA')+'</h2><table><thead><tr><th>Period</th><th>Lord</th><th>Star lord</th><th>Sub lord</th><th>Start / End</th></tr></thead><tbody>'+rows(d.periods.map(p=>({...p,range:p.start+' → '+p.end})),['level','id','star','sub','range'])+'</tbody></table>'+(d.periodReason?'<p>'+esc(d.periodReason)+'</p>':'')+'<h2>My opinion &amp; result</h2><p class="notes">'+esc(d.opinion||'—')+'</p></div>';
}
function refresh(){try{const d=data();window.KPHoraryDBA?.render(d);$('hq-results').innerHTML=snapshot(d);$('hq-status').textContent='Results updated · '+d.query;$('hq-preview').disabled=false;return d;}catch(e){window.KPHoraryDBA?.render({ready:false,reason:e.message});$('hq-status').textContent=e.message;$('hq-preview').disabled=true;$('hq-results').textContent='';return {ready:false,reason:e.message};}}
function preview(){const d=refresh();if(!d.ready)return false;const opened=window.KPChildGenderSheet.preview({title:'Automatic Horary results sheet',html:'<article class="cg-page sheet">'+snapshot(d)+'</article>',css:CSS,lang:window.KPPreferences?.get().language||'english'});const frame=document.querySelector('#cg-preview-dialog iframe');frame?.addEventListener('load',()=>{const doc=frame.contentDocument;doc.fonts.ready.then(()=>{const content=doc.querySelector('.content'),sheet=doc.querySelector('.sheet');if(!content||!sheet)return;const available=sheet.clientHeight-46,scale=Math.min(1,available/Math.max(1,content.scrollHeight));content.style.transform='scale('+scale+')';sheet.dataset.fitted='true';});},{once:true});return opened;}
function init(){
 const section=$('event-promise');if(!section)return;
 const box=document.createElement('article');box.className='card';box.id='hq-panel';box.innerHTML='<h2>Automatic Horary results sheet</h2><div class="actions"><label>Selected query <select id="hq-event"></select></label><label>Theory <select id="hq-method"><option value="fourfold">Four-fold A–D</option><option value="sixfold">Six-fold A–F</option></select></label><button type="button" id="hq-refresh">Update results</button><button type="button" id="hq-preview">A4 single-page report</button></div><label>Question <input id="hq-question" maxlength="700" style="width:100%"></label><label>My opinion &amp; result <textarea id="hq-opinion" maxlength="1500" rows="2" style="width:100%"></textarea></label><p id="hq-status" role="status"></p><details><summary>View automatic results sheet</summary><div id="hq-results"></div></details>';
 section.append(box);for(const e of KPPrediction.getCatalogue().events){const o=document.createElement('option');o.value=e.id;o.textContent=e.event.en||e.event.mr;$('hq-event').append(o);}
 if([...$('hq-event').options].some(o=>o.value===v('ep-event')))$('hq-event').value=v('ep-event');
 box.addEventListener('change',refresh);$('hq-refresh').onclick=refresh;$('hq-preview').onclick=preview;
 const reportButton=document.createElement('button');reportButton.type='button';reportButton.id='report-horary-sheet';reportButton.textContent='Horary query · Single-page A4';reportButton.onclick=preview;$('report').querySelector('.actions').append(reportButton);
 $('event-promise').addEventListener('change',e=>{if(e.target.id==='ep-event'&&[...$('hq-event').options].some(o=>o.value===e.target.value)){$('hq-event').value=e.target.value;refresh();}});
 for(const event of ['chart-saved','chart-manual-change'])window.addEventListener(event,refresh);refresh();
 const style=document.createElement('style');style.textContent='#hq-panel .actions{display:flex;gap:10px;flex-wrap:wrap;align-items:end}#hq-panel .actions label:first-child{flex:1;min-width:240px}#hq-panel select{max-width:100%;width:100%}#hq-results{background:white;color:#142d42;padding:12px}#hq-results table{width:100%;border-collapse:collapse}#hq-results td,#hq-results th{border:1px solid #bed1de;padding:5px}#hq-results h2{font-size:16px;color:#165e79}';document.head.append(style);
}
window.KPHoraryResults=Object.freeze({build,getData:data,snapshot,refresh,preview});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,0));else init();
})();
